// The snippet ex3 asks you to predict. The gate runs it from inside a timer
// callback and compares the labels with your answer. Do not edit this file.

export function run(log: (label: string) => void): void {
  const inner = async (): Promise<void> => {
    log("inner-start");
    await null;
    log("inner-end");
  };

  const outer = async (): Promise<void> => {
    log("outer-start");
    await inner();
    log("outer-end");
  };

  void outer();

  Promise.resolve()
    .then(() => log("then-1"))
    .then(() => log("then-2"));

  log("sync-end");
}
